function clone(value) { return JSON.parse(JSON.stringify(value)); }
// As capas são dados de apresentação: sempre usar os arquivos locais atuais, mesmo em estados salvos
// antes da migração (que ainda apontavam para URLs temporárias do Figma).
function refreshCoverImages(next) {
  (next.courses || []).forEach((course) => { course.image = courseImageUrl(course.id); });
  (next.trails || []).forEach((trail) => { trail.image = trailImageUrl(trail.id); });
  (next.certificates || []).forEach((certificate) => { certificate.image = courseImageUrl(certificate.courseId); });
  return next;
}
function loadState() { try { const stored = localStorage.getItem(STORAGE_KEY); if (!stored) return clone(INITIAL_STATE); const saved = JSON.parse(stored); return refreshCoverImages({ ...clone(INITIAL_STATE), ...saved, preferences: { ...clone(INITIAL_STATE.preferences), ...(saved.preferences || {}) } }); } catch { return clone(INITIAL_STATE); } }
function saveState() { localStorage.setItem(STORAGE_KEY, JSON.stringify(state)); }
function isSessionActive() {
  try {
    const session = JSON.parse(localStorage.getItem(STUDENT_SESSION_KEY) || 'null');
    return session?.authenticated === true;
  } catch {
    return localStorage.getItem(SESSION_KEY) === 'active';
  }
}
function setSession(active) {
  if (active) {
    const session = { authenticated: true, userId: 'student-01' };
    localStorage.setItem(STUDENT_SESSION_KEY, JSON.stringify(session));
    localStorage.setItem(SESSION_KEY, 'active');
  } else {
    localStorage.removeItem(STUDENT_SESSION_KEY);
    localStorage.removeItem(SESSION_KEY);
  }
}
function resetTest() { localStorage.removeItem(STORAGE_KEY); localStorage.removeItem(SIDEBAR_COLLAPSED_KEY); ui.sidebarCollapsed = false; setSession(false); state = clone(INITIAL_STATE); window.history.replaceState({}, '', window.location.pathname); window.location.hash = '#login'; }
if (new URLSearchParams(window.location.search).get('resetTest') === 'true') resetTest();

