function notificationDropdown() { return `<aside class="notification-dropdown" aria-label="Notificações"><header><span>Notificações</span><button class="link-button" data-action="mark-notifications">Marcar como lidas</button></header>${state.notifications.map((item) => `<div class="notification-row"><span class="activity-icon">${icon('bell',15)}</span><p><strong>${escapeHtml(item.title)}</strong><br>${escapeHtml(item.body)}<small>${escapeHtml(item.time)}</small></p></div>`).join('')}</aside>`; }
function renderMessageBubbles(messages) { let lastDay = ''; return messages.map((message) => { const day = message.day && message.day !== lastDay ? `<div class="drawer-day"><span>${escapeHtml(message.day)}</span><i></i><span>${escapeHtml(message.time || '')}</span></div>` : ''; if (message.day) lastDay = message.day; return `${day}<div class="drawer-bubble ${message.mine ? 'mine' : 'received'}"><span>${escapeHtml(message.text)}</span><small>${escapeHtml(message.time || '')}</small></div>`; }).join(''); }
function renderNotesDrawer() { const notebooks = (state.notebooks || []).filter((item) => item.title.toLowerCase().includes(ui.notesSearch.toLowerCase())); if (ui.notesView === 'create') return `<header class="drawer-header"><button class="drawer-icon-button" data-action="notes-back" aria-label="Voltar para Anotações">${icon('back',20)}</button><h2 id="drawer-title">Nova anotação</h2><button class="drawer-icon-button" data-action="close-drawer" aria-label="Fechar Anotações">${icon('close',20)}</button></header><form class="drawer-body notes-create-body" data-form="create-notebook"><div class="notes-create-field"><label for="notebook-name">Nome da anotação</label><input id="notebook-name" name="title" type="text" placeholder="Nome da anotação" autocomplete="off" required /></div><button class="drawer-primary-action" type="submit">Criar anotação</button></form>`; if (ui.notesView === 'editor') { const notebook = state.notebooks.find((item) => item.id === ui.activeNotebookId) || state.notebooks[0]; return `<header class="drawer-header drawer-editor-header"><button class="drawer-icon-button" data-action="notes-back" aria-label="Voltar para a lista de anotações">${icon('back',20)}</button><h2 id="drawer-title">${escapeHtml(notebook?.title || 'Caderno')}</h2><button class="drawer-icon-button" data-action="toggle-notes-menu" aria-label="Opções do caderno">${icon('more',20)}</button>${ui.notesMenuOpen ? `<div class="notes-menu"><button data-action="rename-notebook">Renomear caderno</button><button data-action="delete-notebook">Excluir caderno</button></div>` : ''}</header><div class="drawer-editor-body"><div class="editor-toolbar" role="toolbar" aria-label="Ferramentas de formatação"><button data-action="notes-editor-format" data-format="h2" aria-label="Título 1">H1</button><button data-action="notes-editor-format" data-format="bold" aria-label="Negrito"><strong>B</strong></button><button data-action="notes-editor-format" data-format="italic" aria-label="Itálico"><em>I</em></button><button data-action="notes-editor-format" data-format="draw" aria-label="Desenhar">${icon('draw',18)}</button><button data-action="notes-editor-format" data-format="microphone" aria-label="Gravar áudio">${icon('microphone',18)}</button><button data-action="notes-editor-format" data-format="link" aria-label="Inserir link">${icon('link',18)}</button><button data-action="notes-editor-format" data-format="image" aria-label="Inserir imagem">${icon('image',18)}</button><button data-action="notes-editor-format" data-format="orderedList" aria-label="Lista numerada">${icon('orderedList',18)}</button><button data-action="notes-editor-format" data-format="list" aria-label="Lista com marcadores">${icon('list',18)}</button></div><div class="notebook-editor-content" contenteditable="true" spellcheck="true" data-action="notebook-input" aria-label="Conteúdo de ${escapeHtml(notebook?.title || 'caderno')}">${notebook?.contentHTML || ''}</div></div>`; } return `<header class="drawer-header"><button class="drawer-icon-button" data-action="close-drawer" aria-label="Fechar Anotações">${icon('close',20)}</button><h2 id="drawer-title">Anotações</h2><button class="drawer-icon-button" data-action="drawer-settings" aria-label="Configurações de Anotações">${icon('settings',18)}</button></header><div class="drawer-body notes-drawer-body"><label class="drawer-search"><span>${icon('search',18)}</span><input type="search" value="${escapeHtml(ui.notesSearch)}" placeholder="Pesquise por nome ou e-mail" aria-label="Pesquisar anotações" data-action="notes-search" /></label>${notebooks.length ? `<div class="notebook-grid">${notebooks.map((notebook) => `<button class="notebook-card" data-action="open-notebook" data-id="${notebook.id}"><span class="notebook-icon">${icon('document',24)}</span><strong>${escapeHtml(notebook.title)}</strong><small>${formatNotebookDate(notebook.updatedAt)}</small></button>`).join('')}</div>` : `<div class="notes-empty"><span class="notes-empty-art">${icon('folderAlert',96)}</span><h3>Você ainda não possui<br />anotações criadas</h3></div>`}<button class="drawer-primary-action" data-action="new-notebook">Adicionar nova anotação</button></div>`; }
