function renderAccessibilityDrawer() { return `<header class="drawer-header"><button class="drawer-icon-button" data-action="close-drawer" aria-label="Fechar Acessibilidade">${icon('close',20)}</button><h2 id="drawer-title">Acessibilidade</h2><button class="drawer-icon-button" data-action="drawer-settings" aria-label="Configurações de Acessibilidade">${icon('settings',18)}</button></header><div class="drawer-body accessibility-drawer-body"><p class="drawer-intro">Personalize sua experiência de aprendizagem.</p><div class="accessibility-option"><span class="accessibility-option-icon">${icon('accessibility',22)}</span><div><strong>Alto contraste</strong><small>Aumentar contraste entre textos e superfícies.</small></div><button class="switch ${ui.accessibility.highContrast ? 'on' : ''}" data-action="toggle-accessibility" data-key="highContrast" aria-label="Alternar alto contraste"></button></div><div class="accessibility-option"><span class="accessibility-option-icon">${icon('document',22)}</span><div><strong>Texto ampliado</strong><small>Usar uma escala maior para os textos da interface.</small></div><button class="switch ${ui.accessibility.largeText ? 'on' : ''}" data-action="toggle-accessibility" data-key="largeText" aria-label="Alternar texto ampliado"></button></div><div class="accessibility-option"><span class="accessibility-option-icon">${icon('play',22)}</span><div><strong>Reduzir movimento</strong><small>Reduzir animações e transições da interface.</small></div><button class="switch ${ui.accessibility.reducedMotion ? 'on' : ''}" data-action="toggle-accessibility" data-key="reducedMotion" aria-label="Alternar redução de movimento"></button></div><div class="accessibility-help"><strong>Precisa de ajuda?</strong><p>Use o teclado para navegar. Pressione <kbd>Esc</kbd> para fechar este drawer.</p></div></div>`; }
function renderMessagesDrawer() { if (ui.messageDrawerView === 'list') return `<header class="drawer-header"><button class="drawer-icon-button" data-action="close-drawer" aria-label="Fechar Mensagens">${icon('close',20)}</button><h2 id="drawer-title">Mensagem</h2><button class="drawer-icon-button" data-action="drawer-settings" aria-label="Configurações de Mensagens">${icon('settings',18)}</button></header><div class="drawer-body message-list-drawer"><label class="drawer-search"><span>${icon('search',18)}</span><input type="search" placeholder="Pesquisar conversas" aria-label="Pesquisar conversas" /></label>${state.messages.map((message) => `<button class="drawer-message-list-item" data-action="select-drawer-message" data-id="${message.id}"><span class="avatar">${message.initials}</span><span><strong>${escapeHtml(message.name)}</strong><small>${escapeHtml(message.preview)}</small></span><time>${escapeHtml(message.time)}</time></button>`).join('')}</div>`; const current = state.messages.find((item) => item.id === ui.messageId) || state.messages[0]; return `<header class="drawer-header"><button class="drawer-icon-button" data-action="close-drawer" aria-label="Fechar Mensagens">${icon('close',20)}</button><h2 id="drawer-title">Mensagem</h2><button class="drawer-icon-button" data-action="drawer-settings" aria-label="Configurações de Mensagens">${icon('settings',18)}</button></header><div class="drawer-message-conversation"><div class="drawer-conversation-header"><button class="drawer-icon-button" data-action="messages-back" aria-label="Voltar para conversas">${icon('back',20)}</button><span class="avatar">${current.initials}</span><div class="drawer-contact"><strong>${escapeHtml(current.name)}</strong><small>Estudante</small></div><button class="drawer-icon-button drawer-star" aria-label="Favoritar conversa">${icon('star',18)}</button><button class="drawer-icon-button" data-action="toggle-message-menu" aria-label="Mais opções">${icon('more',18)}</button></div><div class="drawer-message-body">${renderMessageBubbles(current.messages)}</div><form class="drawer-message-compose" data-form="drawer-message"><div class="compose-tools"><button type="button" data-action="compose-format" aria-label="Negrito"><strong>B</strong></button><button type="button" data-action="compose-format" aria-label="Itálico"><em>I</em></button><button type="button" data-action="compose-format" aria-label="Emoji">☺</button><button type="button" data-action="compose-format" aria-label="Adicionar">${icon('plusCircle',17)}</button></div><div class="compose-input-row"><input type="text" placeholder="Digite sua mensagem aqui..." aria-label="Digite sua mensagem aqui" required /><button class="send-button" type="submit" aria-label="Enviar mensagem">${icon('send',18)}</button></div></form></div>`; }
function drawerMarkup() { if (!ui.drawer) return ''; const content = ui.drawer === 'notes' ? renderNotesDrawer() : ui.drawer === 'notifications' ? renderNotificationsDrawer() : ui.drawer === 'messages' ? renderMessagesDrawer() : renderAccessibilityDrawer(); return `<div class="drawer-overlay"><aside class="utility-drawer" data-drawer="${ui.drawer}" role="dialog" aria-modal="true" aria-labelledby="drawer-title" tabindex="-1">${content}</aside></div>`; }
function openDrawer(type) { ui.drawerFocus = document.activeElement; ui.drawerFocusSelector = `[data-action="open-drawer"][data-drawer="${type}"]`; ui.drawer = type; ui.notesMenuOpen = false; if (type === 'notes') ui.notesView = 'list'; if (type === 'messages') ui.messageDrawerView = 'conversation'; render(); requestAnimationFrame(() => document.querySelector('.utility-drawer .drawer-header [data-action="close-drawer"]')?.focus()); }
function closeDrawer() { const returnSelector = ui.drawerFocusSelector; ui.drawer = null; ui.drawerFocus = null; ui.drawerFocusSelector = ''; ui.notesMenuOpen = false; render(); requestAnimationFrame(() => { const target = returnSelector ? document.querySelector(returnSelector) : null; (target || document.body).focus?.(); }); }
function breadcrumbs(items) { return `<div class="breadcrumbs">${items.map((item, index) => index === items.length - 1 ? `<strong>${escapeHtml(item.label)}</strong>` : `<a href="#${item.route || 'home'}" data-route="${item.route || 'home'}">${escapeHtml(item.label)}</a>${icon('chevron',12)}`).join('')}</div>`; }

function renderLogin() { app.innerHTML = `<div class="login-page"><section class="login-panel"><a href="#login" class="brand">${brandLogo()}</a><div class="login-content"><h1>Bem-vindo de volta</h1><p>Insira suas credenciais para acessar seu painel de aprendizagem.</p><form class="login-form" id="login-form"><div class="field"><label for="cpf">CPF</label><input id="cpf" name="cpf" type="text" inputmode="numeric" autocomplete="username" placeholder="000.000.000-00" value="" required /></div><div class="field"><label for="password">Senha</label><div class="password-wrap"><input id="password" name="password" type="password" autocomplete="current-password" placeholder="Digite sua senha" required /><button class="password-toggle" type="button" data-action="toggle-password" aria-label="Mostrar senha">${icon('eye',18)}</button></div></div><div class="form-row"><label class="check"><input type="checkbox" name="remember" /> <span>Lembrar de mim</span></label><button class="link-button" type="button" data-action="forgot-password">Esqueceu a senha?</button></div><div class="login-error" id="login-error" role="alert">CPF ou senha inválidos. Tente novamente com os dados de teste.</div><button class="login-submit" type="submit" id="login-submit">Entrar ${icon('arrow',17)}</button><button class="link-button login-help" type="button" data-action="contact">Tem alguma dúvida? Fale conosco</button></form></div><footer class="login-footer">© 2026 NossaEscolaDigital <u>Segurança & Privacidade</u></footer></section><section class="login-art"><div class="art-copy"><span class="eyebrow">Aprendizagem corporativa</span><h2>Aprenda, evolua e acompanhe sua jornada em um só lugar.</h2><p>Acesse cursos, trilhas e atividades em um ambiente simples, escalável e pronto para diferentes marcas.</p></div><div class="art-mock" aria-hidden="true"><div class="mock-top"></div><div class="mock-body"><div class="mock-sidebar"><span></span><span></span><span></span><span></span><span></span></div><div class="mock-main"><div class="mock-banner"></div><div class="mock-grid"><div class="mock-card"></div><div class="mock-card"></div><div class="mock-card"></div></div></div></div></div></section></div>`; }
function renderHomeLegacy() { const activeCourses = state.courses.filter((course) => course.status !== 'done'); const upcoming = state.activities.slice(0, 3); return appShell('home', `Olá, ${state.user.name} 👋`, `<section class="hero"><div class="hero-content"><h2>Continue sua jornada de aprendizado: acompanhe seu progresso, retome seus cursos e explore novos conteúdos para evoluir suas habilidades.</h2><p>Seu próximo passo está a poucos minutos de distância.</p><button class="button" data-route="course" data-id="ux">Continuar onde parei ${icon('arrow',15)}</button></div></section><div class="section-heading"><h3>Próximas atividades</h3><span class="muted">Tudo em um só lugar</span></div><div class="activity-row">${upcoming.map((activity) => `<article class="activity"><span class="activity-icon">${icon('file',16)}</span><div><strong>${escapeHtml(activity.title)} <span class="tag">${escapeHtml(activity.type)}</span></strong><small>${escapeHtml(getCourse(activity.courseId)?.category || '')}</small><time>${escapeHtml(activity.due)}</time></div></article>`).join('')}</div><div class="section-heading"><h3>Minhas trilhas</h3><div class="toolbar-right"><div class="chips"><button class="chip active">Todos</button><button class="chip">Em andamento</button><button class="chip">Não iniciado</button><button class="chip">Finalizado</button></div><label class="compact-label">Ordenar por<select><option>Mais recentes</option><option>Mais acessados</option></select></label></div></div><div class="card-grid two">${state.trails.map(trailCard).join('')}</div><div class="section-heading"><h3>Meus cursos</h3><a class="link-button" href="#courses" data-route="courses">Ver todos</a></div><div class="card-grid">${activeCourses.slice(0, 3).map(courseCard).join('')}</div><div class="section-heading"><h3>Personalize suas recomendações</h3></div><div class="recommendations"><article class="card course-card"> <div class="course-image">${image(courseImageUrl('logic'), 'Curso recomendado')}</div><div class="card-body"><div class="card-meta"><span class="meta-pill">Recomendado</span><span class="meta-pill">6h</span></div><h3 class="card-title">Comunicação profissional</h3><button class="button primary small side-action" data-action="recommendation">Ver curso</button></div></article><article class="card course-card"><div class="course-image">${image(courseImageUrl('process'), 'Curso recomendado')}</div><div class="card-body"><div class="card-meta"><span class="meta-pill">Recomendado</span><span class="meta-pill">8h</span></div><h3 class="card-title">Gestão de processos produtivos</h3><button class="button primary small side-action" data-route="course" data-id="process">Ver curso</button></div></article><article class="card recommendation-copy"><h3>Personalize suas recomendações e descubra cursos ideais para você!</h3><button class="button primary" data-action="recommendation">Personalizar recomendações</button></article></div>`); }
function recommendationTeaserCard() { return `<article class="card course-card recommendation-teaser" aria-hidden="true"><div class="recommendation-teaser-content"><div class="course-image"><img src="${RECOMMENDATION_PLACEHOLDER}" alt="" loading="lazy" decoding="async" /><span class="course-overlay-icon">${icon('plus', 24)}</span></div><div class="card-body"><div class="card-meta"><span class="meta-pill">Categoria</span><span class="meta-pill">Carga horária</span></div><h3 class="card-title">Curso recomendado</h3><span class="teaser-button">Ver detalhes ${icon('arrow', 16)}</span></div></div></article>`; }
function homeCourseStatusOf(item) { return item.progress >= 100 ? 'Finalizado' : item.progress > 0 ? 'Em andamento' : 'Não iniciado'; }
function statusChips(action, current) { return `<div class="compact-label"><span>Status</span><div class="chips" role="group" aria-label="Filtrar por status">${['Todos', 'Em andamento', 'Não iniciado', 'Finalizado'].map((status) => `<button class="chip ${current === status ? 'active' : ''}" type="button" data-action="${action}" data-value="${status}" aria-pressed="${current === status}">${status}</button>`).join('')}</div></div>`; }
function recommendationCard(course, reason) { const card = courseCard(course); return reason ? card.replace('<div class="course-footer">', `<p class="card-recommendation-reason">${escapeHtml(reason)}</p><div class="course-footer">`) : card; }
function getRecommendationEntries() { const configured = state.preferences.recommendationsConfigured && state.preferences.recommendationInterests?.length; const pool = state.courses.filter((course) => course.status !== 'done' && !course.blocked); if (!configured) return pool.slice(0, 2).map((course) => ({ course, reason: '' })); const interests = state.preferences.recommendationInterests; return pool.map((course, index) => { const matches = (COURSE_INTERESTS[course.id] || []).filter((interest) => interests.includes(interest)); return { course, matches, score: matches.length, index }; }).sort((a, b) => b.score - a.score || a.index - b.index).slice(0, 2).map(({ course, matches }) => ({ course, reason: matches.length ? `Porque você se interessa por ${matches[0]}` : 'Recomendado com base nos seus interesses' })); }
function renderHome() {
  const upcoming = state.activities.slice(0, 3);
  const recommendations = getRecommendationEntries();
  const configured = state.preferences.recommendationsConfigured;
  const revealing = ui.recommendationsRevealed;
  ui.recommendationsRevealed = false;
  const trails = state.trails.filter((trail) => ui.homeTrailStatus === 'Todos' || homeCourseStatusOf(trail) === ui.homeTrailStatus);
  const myCourses = state.courses.filter(isCourseEnrolled).filter((course) => ui.homeCourseStatus === 'Todos' || statusLabel(course.status) === ui.homeCourseStatus);
  const pageCount = Math.max(1, Math.ceil(myCourses.length / ui.homeCoursesPerPage));
  ui.homeCoursePage = Math.min(ui.homeCoursePage, pageCount - 1);
  const pageStart = ui.homeCoursePage * ui.homeCoursesPerPage;
  const visibleCourses = myCourses.slice(pageStart, pageStart + ui.homeCoursesPerPage);
  const sortSelect = `<label class="compact-label">Ordenar por<select><option>Mais recentes</option><option>Mais acessados</option></select></label>`;
  const emptyState = (message) => `<div class="empty">${icon('search', 34)}<strong>Nenhum item encontrado</strong><p>${message}</p></div>`;
  const carouselNav = pageCount > 1 ? `<div class="carousel-nav" role="group" aria-label="Navegar pelos cursos"><button class="carousel-button" type="button" data-action="home-courses-page" data-step="-1" aria-label="Cursos anteriores" ${ui.homeCoursePage === 0 ? 'disabled' : ''}>${icon('back', 20)}</button><span class="carousel-status" aria-live="polite">${ui.homeCoursePage + 1} de ${pageCount}</span><button class="carousel-button" type="button" data-action="home-courses-page" data-step="1" aria-label="Próximos cursos" ${ui.homeCoursePage >= pageCount - 1 ? 'disabled' : ''}>${icon('arrow', 20)}</button></div>` : '';
  const recommendationCards = configured
    ? recommendations.map(({ course, reason }) => recommendationCard(course, reason)).join('')
    : recommendationTeaserCard() + recommendationTeaserCard();
  return appShell('home', `Olá, ${state.user.name} 👋`, `<section class="hero" style="--hero-shapes:url('${BANNER_SHAPES}')"><div class="hero-content"><h2>Continue sua jornada de aprendizado: acompanhe seu progresso, retome seus cursos e explore novos conteúdos para evoluir suas habilidades.</h2><div class="hero-actions"><button class="button" data-route="course" data-id="ux">Continuar de onde parei</button><button class="button hero-link" data-route="catalog">Conhecer cursos novos</button></div></div></section>`
    + `<div class="section-heading"><h3>Próximas atividades</h3></div><div class="activity-row">${upcoming.map((activity) => `<article class="activity"><span class="activity-icon">${icon('file',24)}</span><div><strong>${escapeHtml(activity.title)} <span class="tag">${escapeHtml(activity.type)}</span></strong><small>${escapeHtml(getCourse(activity.courseId)?.category || '')}</small><time>${escapeHtml(activity.due)}</time></div></article>`).join('')}</div>`
    + `<div class="section-heading"><h3>Minhas trilhas</h3><div class="toolbar-right">${statusChips('home-trail-filter', ui.homeTrailStatus)}${sortSelect}</div></div>${trails.length ? `<div class="card-grid">${trails.map(trailCard).join('')}</div>` : emptyState('Nenhuma trilha com este status.')}`
    + `<div class="section-heading"><h3>Meus cursos</h3><div class="toolbar-right">${statusChips('home-course-filter', ui.homeCourseStatus)}${sortSelect}</div></div>${visibleCourses.length ? `<div class="card-grid home-course-carousel">${visibleCourses.map(courseCard).join('')}</div>${carouselNav}` : emptyState('Nenhum curso com este status.')}<div class="section-link-row"><a class="link-button" href="#courses" data-route="courses">Ver todos os cursos</a></div>`
    + `<div class="section-heading"><h3>${configured ? 'Recomendados para você' : 'Personalize suas recomendações'}</h3>${configured ? '<button class="link-button" data-action="personalize-recommendations">Editar preferências</button>' : ''}</div><div class="recommendations ${configured ? 'is-configured' : 'is-locked'} ${revealing ? 'is-revealing' : ''}">${recommendationCards}<article class="card recommendation-copy"><h3>${configured ? 'Quer refinar ainda mais suas recomendações?' : 'Personalize suas recomendações e descubra cursos ideais para você!'}</h3><button class="button primary" data-action="personalize-recommendations">${configured ? 'Editar preferências' : 'Personalizar recomendações'}</button></article></div>`);
}
function renderCourses() { const enrolledCourses = state.courses.filter(isCourseEnrolled); const filtered = enrolledCourses.filter((course) => (ui.courseStatus === 'Todos' || statusLabel(course.status) === ui.courseStatus) && course.title.toLowerCase().includes(ui.courseSearch.toLowerCase())); return appShell('courses', 'Meus cursos', `<div class="page-heading">${breadcrumbs([{ label: 'Início', route: 'home' }, { label: 'Meus cursos' }])}<div><h2>Meus cursos</h2><p>Acompanhe sua evolução e continue aprendendo.</p></div></div><div class="toolbar"><div class="toolbar-left"><div class="compact-label course-search-group"><span id="course-search-label">Buscar e filtrar</span><label class="search-field"><span class="icon">${icon('search',16)}</span><input type="search" value="${escapeHtml(ui.courseSearch)}" placeholder="Buscar por cursos, tópicos" aria-labelledby="course-search-label" data-action="course-search" /></label></div><div><span class="compact-label">Status</span><div class="chips">${['Todos','Em andamento','Não iniciado','Finalizado'].map((status) => `<button class="chip ${ui.courseStatus === status ? 'active' : ''}" data-action="course-filter" data-value="${status}">${status}</button>`).join('')}</div></div></div><label class="compact-label">Ordenar por<select><option>Mais recentes</option><option>Mais acessados</option><option>Nome</option></select></label></div>${filtered.length ? `<div class="card-grid">${filtered.map(courseCard).join('')}</div>` : `<div class="empty">${icon('search',34)}<strong>Nenhum curso encontrado</strong><p>Tente buscar por outro termo ou remova os filtros.</p></div>`}<div class="toolbar" style="margin-top:22px"><span class="muted">1–${filtered.length} de ${enrolledCourses.length}</span><div class="chips"><button class="chip">‹</button><button class="chip active">1</button><button class="chip">2</button><button class="chip">›</button></div></div>`); }
function courseContentMarkup(course, next) {
  const lessons = allLessons(course);
  const completed = lessons.filter((lesson) => lesson.done).length;
  return '<div class="course-tab-panel" id="course-content-panel" role="tabpanel" aria-labelledby="course-content-tab"><div class="section-heading"><h3>Conteúdo do curso</h3><span class="muted">' + completed + ' de ' + lessons.length + ' concluídos</span></div>' + course.modules.map((module) => '<article class="module"><div class="module-header"><span>' + escapeHtml(module.title) + '</span><span class="muted">' + module.lessons.filter((lesson) => lesson.done).length + '/' + module.lessons.length + '</span></div><div class="lesson-list">' + module.lessons.map((lesson) => '<div class="lesson-item ' + (lesson.id === next.id ? 'current' : '') + '" data-route="lesson" data-course="' + course.id + '" data-lesson="' + lesson.id + '" role="button" tabindex="0"><span class="lesson-check ' + (lesson.done ? 'done' : '') + '">' + (lesson.done ? icon('check', 13) : '') + '</span><span>' + escapeHtml(lesson.title) + '</span><span class="lesson-type">' + escapeHtml(lesson.type) + ' · ' + lesson.duration + '</span></div>').join('') + '</div></article>').join('') + '</div>';
}

function courseAboutMarkup(course) {
  const info = [['Categoria', course.category], ['Carga horária', course.workload], ['Instrutor', course.instructor], ['Conteúdos', allLessons(course).length + ' aulas']];
  return '<div class="course-tab-panel course-about" id="course-about-panel" role="tabpanel" aria-labelledby="course-about-tab"><div class="course-about-section"><h3>Sobre o curso</h3><p>' + escapeHtml(course.description) + '</p></div><div class="course-about-section"><h3>Informações do curso</h3><div class="course-info-grid">' + info.map(([label, value]) => '<div class="course-info-item"><span>' + escapeHtml(label) + '</span><strong>' + escapeHtml(value) + '</strong></div>').join('') + '</div></div><div class="course-certificate-note"><div><strong>Certificado</strong><p>Ao concluir todos os conteúdos, seu certificado ficará disponível automaticamente.</p></div><button class="button secondary small" data-action="open-certificate" data-course="' + course.id + '">Ver certificado</button></div></div>';
}

function courseTabsMarkup(activeTab) {
  const contentActive = activeTab === 'content';
  return '<nav class="course-tabs" role="tablist" aria-label="Seções do curso"><button id="course-content-tab" class="course-tab ' + (contentActive ? 'active' : '') + '" type="button" role="tab" aria-selected="' + contentActive + '" aria-controls="course-content-panel" data-action="course-tab" data-tab="content">Conteúdo do curso</button><button id="course-about-tab" class="course-tab ' + (!contentActive ? 'active' : '') + '" type="button" role="tab" aria-selected="' + (!contentActive) + '" aria-controls="course-about-panel" data-action="course-tab" data-tab="about">Sobre o curso</button></nav>';
}

function unenrolledCourseContentMarkup(course) {
  return course.modules.map((module, index) => '<details class="module preview-module" open><summary class="module-header"><span>' + String(index + 1).padStart(2, '0') + ' — ' + escapeHtml(module.title) + '</span><span class="module-summary"><span class="muted">' + module.lessons.length + ' conteúdos</span>' + icon('chevron', 14) + '</span></summary><div class="lesson-list">' + module.lessons.map((lesson) => '<div class="lesson-item" data-route="lesson" data-course="' + course.id + '" data-lesson="' + lesson.id + '" role="button" tabindex="0"><span class="lesson-check ' + (lesson.done ? 'done' : '') + '">' + (lesson.done ? icon('check', 13) : '') + '</span><span>' + escapeHtml(lesson.title) + '</span><span class="lesson-type">' + escapeHtml(lesson.type) + ' · ' + lesson.duration + '</span></div>').join('') + '</div></details>').join('');
}

function renderUnenrolledCourse(course) {
  const lessons = allLessons(course);
  return appShell('catalog', course.title, breadcrumbs([{ label: 'Início', route: 'home' }, { label: 'Cursos disponíveis', route: 'catalog' }, { label: course.title }]) + '<div class="unenrolled-course-layout"><main class="unenrolled-course-main"><section class="unenrolled-course-banner"><div class="unenrolled-course-banner-image">' + image(course.image, course.title) + '<div class="unenrolled-course-banner-overlay"><div class="card-meta"><span class="meta-pill">' + escapeHtml(course.category) + '</span></div><h2>' + escapeHtml(course.title) + '</h2></div></div></section><section class="unenrolled-course-section"><div class="course-section-heading"><span class="section-heading-marker" aria-hidden="true"></span><h3>O que você vai aprender</h3></div><p class="unenrolled-course-description">' + escapeHtml(course.description) + '</p></section><section class="unenrolled-course-section"><div class="course-section-heading"><span class="section-heading-marker" aria-hidden="true"></span><h3>Conteúdo do curso</h3><span class="muted">' + lessons.length + ' conteúdos</span></div><div class="preview-modules">' + unenrolledCourseContentMarkup(course) + '</div></section></main><aside class="unenrolled-course-aside"><article class="card enrollment-card"><h3>Acesse este curso</h3><p>Acesse os conteúdos deste curso na Nossa Escola Digital.</p><ul class="enrollment-benefits"><li>' + icon('check', 14) + '<span>Certificado digital</span></li><li>' + icon('check', 14) + '<span>Material de apoio</span></li><li>' + icon('check', 14) + '<span>Aulas online</span></li></ul><button class="button primary enrollment-cta" data-action="enroll-course" data-id="' + course.id + '">Inscrever-se ' + icon('arrow', 15) + '</button></article></aside></div>');
}

function renderCourse(id) {
  const course = getCourse(id) || state.courses[0];
  const completion = syncCourseProgress(course);
  if (!isCourseEnrolled(course)) return renderUnenrolledCourse(course);
  const next = firstOpenLesson(course);
  const activeTab = ui.courseTab === 'about' ? 'about' : 'content';
  const tabContent = activeTab === 'about' ? courseAboutMarkup(course) : courseContentMarkup(course, next);
return appShell('courses', course.title, breadcrumbs([{ label: 'Início', route: 'home' }, { label: 'Meus cursos', route: 'courses' }, { label: course.title }]) + '<section class="detail-hero"><div class="detail-image">' + image(course.image, course.title) + '</div><div><div class="card-meta"><span class="meta-pill">' + escapeHtml(course.category) + '</span><span class="meta-pill">' + escapeHtml(course.workload) + '</span><span class="status ' + course.status + '">' + statusLabel(course.status) + '</span></div><h2>' + escapeHtml(course.title) + '</h2><p>' + escapeHtml(course.description) + '</p><p style="margin-top:12px">Instrutor: <strong>' + escapeHtml(course.instructor) + '</strong></p></div><aside class="detail-aside"><div class="metric"><span>Seu progresso</span><strong>' + course.progress + '%</strong></div><div class="progress-line"><span style="width:' + course.progress + '%"></span></div><div class="metric"><span>Carga horária</span><strong>' + escapeHtml(course.workload) + '</strong></div><div class="metric"><span>Conteúdos</span><strong>' + allLessons(course).length + ' aulas</strong></div><button class="button primary" data-route="lesson" data-course="' + course.id + '" data-lesson="' + next.id + '">' + (course.progress ? 'Continuar de onde parei' : 'Iniciar curso') + ' ' + icon('arrow', 15) + '</button></aside></section><div class="detail-layout course-detail-layout"><section class="course-main">' + courseTabsMarkup(activeTab) + tabContent + '</section><aside><article class="card side-card"><h3>Materiais</h3><div class="file-box"><span class="icon">' + icon('file', 22) + '</span><div><strong style="font-size:12px">Guia do estudante.pdf</strong><small style="display:block;color:var(--text-500);margin-top:4px">2,4 MB</small></div></div></article></aside></div>');
}
function renderLessonLegacy(courseId, lessonId) { const course = getCourse(courseId) || state.courses[0]; const lesson = getLesson(course, lessonId) || firstOpenLesson(course); const lessons = allLessons(course); const index = lessons.findIndex((item) => item.id === lesson.id); const previous = lessons[index - 1]; const next = lessons[index + 1]; const typeContent = lesson.type === 'video' ? `<div class="video-player"><button class="play" data-action="play-video" aria-label="Reproduzir aula">${icon('play',27)}</button></div>` : lesson.type === 'podcast' ? `<div class="card file-box" style="min-height:180px;justify-content:center"><span class="icon" style="width:48px;height:48px;color:var(--primary-600)">${icon('message',48)}</span><div><strong>Podcast da aula</strong><p class="muted">Ouça o conteúdo enquanto acompanha sua jornada.</p><button class="button primary small" data-action="play-video">Reproduzir áudio</button></div></div>` : lesson.type === 'task' ? `<article class="card form-card"><h2>Atividade avaliativa</h2><p class="muted">Responda ao exercício e envie sua resposta para registrar a conclusão.</p><div class="field"><label for="answer">Sua resposta</label><textarea id="answer" placeholder="Digite sua resposta..."></textarea></div><button class="button primary" data-action="submit-activity" data-course="${course.id}" data-lesson="${lesson.id}">Enviar atividade ${icon('arrow',15)}</button></article>` : `<article class="rich-content"><h2>Aprendendo na prática</h2><p>Uma boa experiência começa por entender o contexto de quem utiliza o produto. Neste conteúdo você vai conhecer ferramentas e exemplos para aplicar os conceitos no seu dia a dia.</p><p>Observe as necessidades, formule hipóteses e valide suas decisões com as pessoas envolvidas.</p><ul><li>Organize os principais aprendizados.</li><li>Registre evidências e oportunidades.</li><li>Compartilhe os próximos passos com o time.</li></ul><div class="file-box"><span class="icon">${icon('file',22)}</span><div><strong>Material complementar</strong><small style="display:block;color:var(--text-500);margin-top:4px">Baixe o guia da aula para consultar depois.</small></div><button class="button secondary small" data-action="download-material">Baixar</button></div></article>`; return `<div class="lesson-shell"><header class="lesson-header"><a href="#course?id=${course.id}" class="icon-button" data-route="course" data-id="${course.id}" aria-label="Voltar para o curso">${icon('back')}</a><a href="#home" class="brand">${brandLogo()}</a><span class="lesson-name">${escapeHtml(course.title)}</span><div class="lesson-progress"><small><span>Progresso do curso</span><strong>${course.progress}%</strong></small><div class="progress-line"><span style="width:${course.progress}%"></span></div></div><button class="icon-button" data-route="help" aria-label="Ajuda">${icon('help')}</button></header><main class="lesson-layout"><aside class="lesson-sidebar"><h3>Conteúdo do curso</h3>${course.modules.map((module) => `<div class="lesson-module-title">${escapeHtml(module.title)}</div>${module.lessons.map((item) => `<div class="lesson-item ${item.id === lesson.id ? 'current' : ''}" data-route="lesson" data-course="${course.id}" data-lesson="${item.id}" role="button" tabindex="0"><span class="lesson-check ${item.done ? 'done' : ''}">${item.done ? icon('check',13) : ''}</span><span>${escapeHtml(item.title)}</span></div>`).join('')}`).join('')}</aside><section class="lesson-main"><div class="breadcrumbs">${icon('book',12)} ${escapeHtml(course.title)} <span>›</span> <strong>${escapeHtml(lesson.title)}</strong></div><h1>${escapeHtml(lesson.title)}</h1><p class="lesson-subtitle">${escapeHtml(lesson.duration)} · ${lesson.done ? 'Conteúdo concluído' : 'Conteúdo em andamento'}</p>${typeContent}<div class="lesson-actions"><button class="button ghost" ${previous ? `data-route="lesson" data-course="${course.id}" data-lesson="${previous.id}"` : 'disabled'}>${icon('back',15)} Aula anterior</button><button class="button ${lesson.done ? 'secondary' : 'primary'}" data-action="complete-lesson" data-course="${course.id}" data-lesson="${lesson.id}">${lesson.done ? 'Concluída' : 'Marcar como concluída'} ${icon('check',15)}</button><button class="button secondary" ${next ? `data-route="lesson" data-course="${course.id}" data-lesson="${next.id}"` : `data-route="course" data-id="${course.id}"`}>${next ? 'Próxima aula' : 'Voltar ao curso'} ${icon('arrow',15)}</button></div></section></main></div>`; }
function ensureQuizState(course, lesson) { if (ui.quizCourseId !== course.id || ui.quizLessonId !== lesson.id) { ui.quizCourseId = course.id; ui.quizLessonId = lesson.id; ui.quizMode = lesson.done ? 'completed' : 'intro'; ui.quizIndex = 0; ui.quizAnswers = { ...(lesson.quizAnswers || {}) }; } if (lesson.done) ui.quizMode = 'completed'; }
function renderQuizContent(course, lesson) { const questions = QUIZ_QUESTIONS; if (ui.quizMode === 'completed') return `<article class="quiz-complete card"><span class="quiz-success-icon">${icon('check',28)}</span><h2>Questionário concluído</h2><p>Você concluiu esta atividade.</p><button class="button primary" data-route="course" data-id="${course.id}">Voltar para o curso ${icon('arrow',15)}</button></article>`; if (ui.quizMode === 'intro') return `<article class="quiz-intro card"><span class="quiz-label">ATIVIDADE</span><h2>Questionário final</h2><p>Responda às questões para concluir este conteúdo. Qualquer alternativa selecionada será aceita.</p><div class="quiz-summary"><div><strong>4</strong><span>Questões</span></div><div><strong>1</strong><span>Tentativa</span></div><div><strong>5 min</strong><span>Tempo estimado</span></div></div><button class="button primary" data-action="start-quiz">Começar questionário ${icon('arrow',15)}</button></article>`; const question = questions[ui.quizIndex]; const selected = ui.quizAnswers[question.id]; const last = ui.quizIndex === questions.length - 1; return `<article class="quiz-question card"><div class="quiz-question-top"><span>Questão ${ui.quizIndex + 1} de ${questions.length}</span><span>${Object.keys(ui.quizAnswers).length}/${questions.length} respondidas</span></div><div class="progress-line"><span style="width:${((ui.quizIndex + 1) / questions.length) * 100}%"></span></div><h2>${escapeHtml(question.question)}</h2><div class="quiz-options">${question.options.map((option) => `<button type="button" class="quiz-option ${selected === option ? 'selected' : ''}" data-action="select-quiz-answer" data-value="${escapeHtml(option)}"><span class="quiz-radio">${selected === option ? icon('check',13) : ''}</span><span>${escapeHtml(option)}</span></button>`).join('')}</div>${ui.quizFeedback ? `<div class="quiz-feedback" role="alert">${escapeHtml(ui.quizFeedback)}</div>` : ''}<div class="quiz-navigation"><button class="button ghost" data-action="quiz-previous" ${ui.quizIndex === 0 ? 'disabled' : ''}>${icon('back',15)} Anterior</button><button class="button primary" data-action="quiz-next">${last ? 'Finalizar questionário' : 'Próximo'} ${icon('arrow',15)}</button></div></article>`; }
function renderLessonContent(course, lesson) { if (lesson.type === 'video') return `<div class="video-player"><button class="play" data-action="play-video" aria-label="Reproduzir aula">${icon('play',27)}</button></div>`; if (lesson.type === 'podcast') return `<div class="card file-box" style="min-height:180px;justify-content:center"><span class="icon" style="width:48px;height:48px;color:var(--primary-600)">${icon('message',48)}</span><div><strong>Podcast da aula</strong><p class="muted">Ouça o conteúdo enquanto acompanha sua jornada.</p><button class="button primary small" data-action="play-video">Reproduzir áudio</button></div></div>`; if (lesson.type === 'task') return `<article class="card form-card"><h2>Atividade avaliativa</h2><p class="muted">Responda ao exercício e envie sua resposta para registrar a conclusão.</p><div class="field"><label for="answer">Sua resposta</label><textarea id="answer" placeholder="Digite sua resposta..."></textarea></div><button class="button primary" data-action="submit-activity" data-course="${course.id}" data-lesson="${lesson.id}">Enviar atividade ${icon('arrow',15)}</button></article>`; return `<article class="rich-content"><h2>Aprendendo na prática</h2><p>Uma boa experiência começa por entender o contexto de quem utiliza o produto. Neste conteúdo você vai conhecer ferramentas e exemplos para aplicar no seu dia a dia.</p><p>Observe as necessidades, formule hipóteses e valide suas decisões com as pessoas envolvidas.</p><ul><li>Organize os principais aprendizados.</li><li>Registre evidências e oportunidades.</li><li>Compartilhe os próximos passos com o time.</li></ul><div class="file-box"><span class="icon">${icon('file',22)}</span><div><strong>Material complementar</strong><small style="display:block;color:var(--text-500);margin-top:4px">Baixe o guia da aula para consultar depois.</small></div><button class="button secondary small" data-action="download-material">Baixar</button></div></article>`; }
function renderLesson(courseId, lessonId) { const course = getCourse(courseId) || state.courses[0]; const lesson = getLesson(course, lessonId) || firstOpenLesson(course); const lessons = allLessons(course); const index = lessons.findIndex((item) => item.id === lesson.id); const previous = lessons[index - 1]; const next = lessons[index + 1]; const isQuiz = lesson.type === 'quiz'; if (isQuiz) ensureQuizState(course, lesson); const typeContent = isQuiz ? renderQuizContent(course, lesson) : renderLessonContent(course, lesson); const lessonActions = isQuiz ? '' : `<div class="lesson-actions"><button class="button ghost" ${previous ? `data-route="lesson" data-course="${course.id}" data-lesson="${previous.id}"` : 'disabled'}>${icon('back',15)} Aula anterior</button><button class="button ${lesson.done ? 'secondary' : 'primary'}" data-action="complete-lesson" data-course="${course.id}" data-lesson="${lesson.id}">${lesson.done ? 'Concluída' : 'Marcar como concluída'} ${icon('check',15)}</button><button class="button secondary" ${next ? `data-route="lesson" data-course="${course.id}" data-lesson="${next.id}"` : `data-route="course" data-id="${course.id}"`}>${next ? 'Próxima aula' : 'Voltar ao curso'} ${icon('arrow',15)}</button></div>`; return `<div class="lesson-shell"><header class="lesson-header"><a href="#course?id=${course.id}" class="icon-button" data-route="course" data-id="${course.id}" aria-label="Voltar para o curso">${icon('back')}</a><a href="#home" class="brand">${brandLogo()}</a><span class="lesson-name">${escapeHtml(course.title)}</span><div class="lesson-progress"><small><span>Progresso do curso</span><strong>${course.progress}%</strong></small><div class="progress-line"><span style="width:${course.progress}%"></span></div></div><button class="icon-button" data-route="help" aria-label="Ajuda">${icon('help')}</button></header><main class="lesson-layout"><aside class="lesson-sidebar"><h3>Conteúdo do curso</h3>${course.modules.map((module) => `<div class="lesson-module-title">${escapeHtml(module.title)}</div>${module.lessons.map((item) => `<div class="lesson-item ${item.id === lesson.id ? 'current' : ''}" data-route="lesson" data-course="${course.id}" data-lesson="${item.id}" role="button" tabindex="0"><span class="lesson-check ${item.done ? 'done' : ''}">${item.done ? icon('check',13) : ''}</span><span>${escapeHtml(item.title)}</span></div>`).join('')}`).join('')}</aside><section class="lesson-main"><div class="breadcrumbs">${icon('book',12)} ${escapeHtml(course.title)} <span>›</span> <strong>${escapeHtml(lesson.title)}</strong></div><h1>${escapeHtml(lesson.title)}</h1><p class="lesson-subtitle">${escapeHtml(lesson.duration)} · ${lesson.done ? 'Conteúdo concluído' : 'Conteúdo em andamento'}</p>${typeContent}${lessonActions}</section></main></div>`; }
function renderTrails() { const filtered = state.trails.filter((trail) => trail.title.toLowerCase().includes(ui.trailSearch.toLowerCase())); return appShell('trails', 'Minhas trilhas', `${breadcrumbs([{ label: 'Início', route: 'home' }, { label: 'Minhas trilhas' }])}<div class="page-heading"><div><h2>Minhas trilhas</h2><p>Jornadas organizadas para desenvolver novas competências.</p></div><button class="button primary" data-route="catalog">Explorar cursos ${icon('arrow',15)}</button></div><div class="toolbar"><label class="search-field"><span class="icon">${icon('search',16)}</span><input type="search" value="${escapeHtml(ui.trailSearch)}" placeholder="Buscar por trilhas" data-action="trail-search" /></label><div class="chips"><button class="chip active">Todos</button><button class="chip">Em andamento</button><button class="chip">Finalizado</button></div></div><div class="card-grid">${filtered.map(trailCard).join('')}</div>`); }
function renderTrail(id) { const trail = getTrail(id) || state.trails[0]; const courses = trail.courseIds.map(getCourse).filter(Boolean); return appShell('trails', trail.title, `${breadcrumbs([{ label: 'Início', route: 'home' }, { label: 'Minhas trilhas', route: 'trails' }, { label: trail.title }])}<section class="detail-hero"><div class="detail-image">${image(trail.image, trail.title)}</div><div><div class="card-meta"><span class="meta-pill">${escapeHtml(trail.category)}</span><span class="meta-pill">${courses.length} cursos</span></div><h2>${escapeHtml(trail.title)}</h2><p>${escapeHtml(trail.description)}</p></div><aside class="detail-aside"><div class="metric"><span>Progresso da trilha</span><strong>${trail.progress}%</strong></div><div class="progress-line"><span style="width:${trail.progress}%"></span></div><button class="button primary" data-route="course" data-id="${courses[0]?.id}">Continuar trilha ${icon('arrow',15)}</button></aside></section><div class="section-heading"><h3>Cursos da trilha</h3><span class="muted">Obrigatórios e recomendados</span></div><div class="card-grid">${courses.map(courseCard).join('')}</div>`); }
function renderCatalog(showcase = false) { const availableCourses = state.courses.filter((course) => !isCourseEnrolled(course)); const list = availableCourses.filter((course) => !showcase || course.status === 'pending').filter((course) => course.title.toLowerCase().includes(ui.catalogSearch.toLowerCase())); return appShell('catalog', showcase ? 'Vitrine' : 'Cursos disponíveis', `${breadcrumbs([{ label: 'Início', route: 'home' }, { label: showcase ? 'Vitrine' : 'Cursos disponíveis' }])}<div class="page-heading"><div><h2>${showcase ? 'Vitrine' : 'Cursos disponíveis'}</h2><p>${showcase ? 'Descubra experiências de aprendizagem selecionadas para você.' : 'Encontre novos conteúdos para continuar evoluindo.'}</p></div><button class="button secondary" data-route="courses">Meus cursos</button></div><div class="toolbar"><label class="search-field"><span class="icon">${icon('search',16)}</span><input type="search" value="${escapeHtml(ui.catalogSearch)}" placeholder="Buscar por cursos, tópicos" data-action="catalog-search" /></label><div class="chips"><button class="chip active">Todos</button><button class="chip">Tecnologia</button><button class="chip">Gestão</button><button class="chip">Desenvolvimento</button></div></div>${list.length ? `<div class="card-grid">${list.map((course) => courseCard(course, { catalog: true })).join('')}</div>` : `<div class="empty">${icon('search',34)}<strong>Nenhum curso disponível</strong><p>Não encontramos resultados para sua busca.</p></div>`}`); }
function renderCertificatesLegacy() { return appShell('certificates', 'Certificados', `${breadcrumbs([{ label: 'Início', route: 'home' }, { label: 'Certificados' }])}<div class="page-heading"><div><h2>Certificados</h2><p>Consulte e compartilhe suas conquistas.</p></div><label class="search-field"><span class="icon">${icon('search',16)}</span><input type="search" placeholder="Buscar por cursos" /></label></div><div class="card-grid">${state.certificates.map((certificate) => `<article class="card course-card" data-route="certificate" data-id="${certificate.id}" tabindex="0" role="link"><div class="course-image">${image(certificate.image, certificate.title)}</div><div class="card-body"><div class="card-meta"><span class="meta-pill">Certificado</span><span class="meta-pill">${escapeHtml(certificate.issued)}</span></div><h3 class="card-title">${escapeHtml(certificate.title)}</h3><div class="course-footer"><span>Concluído</span><button class="button primary small" data-action="download-certificate" data-id="${certificate.id}">${icon('download',13)} Baixar</button></div></div></article>`).join('')}</div>`); }
function renderCertificates() { syncAllCourseProgress(); return appShell('certificates', 'Certificados', `${breadcrumbs([{ label: 'Início', route: 'home' }, { label: 'Certificados' }])}<div class="page-heading"><div><h2>Certificados</h2><p>Consulte e compartilhe suas conquistas.</p></div></div><div class="card-grid">${state.certificates.map((certificate) => { const available = isCertificateAvailable(certificate); return `<article class="card course-card ${available ? '' : 'certificate-locked'}" ${available ? `data-route="certificate" data-id="${certificate.id}"` : ''} tabindex="0" role="${available ? 'link' : 'article'}"><div class="course-image">${image(certificate.image, certificate.title)}</div><div class="card-body"><div class="card-meta"><span class="meta-pill">Certificado</span><span class="meta-pill">${escapeHtml(certificate.issued)}</span></div><h3 class="card-title">${escapeHtml(certificate.title)}</h3><div class="course-footer"><span class="status ${available ? 'done' : 'pending'}">${available ? 'Disponível' : 'Indisponível'}</span>${available ? `<button class="button primary small" data-action="download-certificate" data-id="${certificate.id}">${icon('download',13)} Baixar</button>` : '<span class="muted">Conclua o curso</span>'}</div></div></article>`; }).join('')}</div>`); }
function renderCertificate(id) { const certificate = state.certificates.find((item) => item.id === id) || state.certificates[0]; if (!isCertificateAvailable(certificate)) return appShell('certificates', 'Certificado', `${breadcrumbs([{ label: 'Início', route: 'home' }, { label: 'Certificados', route: 'certificates' }, { label: certificate.title }])}<div class="empty">${icon('certificate',34)}<strong>Certificado indisponível</strong><p>Conclua todos os conteúdos obrigatórios para liberar este certificado.</p><button class="button primary" data-route="course" data-id="${certificate.courseId}">Voltar para o curso</button></div>`); return appShell('certificates', 'Certificado', `${breadcrumbs([{ label: 'Início', route: 'home' }, { label: 'Certificados', route: 'certificates' }, { label: certificate.title }])}<div class="detail-layout"><section class="card" style="padding:22px"><div class="certificate-paper"><div class="certificate-decoration"></div><p>Certificado de conclusão</p><h2>${escapeHtml(certificate.title)}</h2><span>Concedido a</span><h3>${escapeHtml(state.user.name)}</h3><p>pela conclusão da jornada de aprendizagem em ${escapeHtml(certificate.issued)}.</p><strong>${escapeHtml(certificate.code)}</strong></div></section><aside><article class="card side-card"><h3>Informações detalhadas</h3><div class="metric"><span>Curso</span><strong>${escapeHtml(certificate.title)}</strong></div><div class="metric" style="margin-top:12px"><span>Data de emissão</span><strong>${escapeHtml(certificate.issued)}</strong></div><button class="button primary side-action" data-action="download-certificate" data-id="${certificate.id}">${icon('download',15)} Baixar PDF</button><button class="button secondary side-action" data-action="share-certificate">Compartilhar</button></article></aside></div>`); }
function renderCalendar() { const days = ['Dom','Seg','Ter','Qua','Qui','Sex','Sáb']; const dates = Array.from({ length: 35 }, (_, index) => index - 2); const dayEvents = (number) => state.events.filter((event) => Number(event.date.slice(-2)) === number); return appShell('calendar', 'Calendário', `${breadcrumbs([{ label: 'Início', route: 'home' }, { label: 'Calendário' }])}<div class="page-heading"><div><h2>Calendário</h2><p>Visualize prazos, encontros e próximos eventos.</p></div><button class="button primary" data-action="new-event">Novo evento ${icon('arrow',15)}</button></div><div class="toolbar"><div class="chips"><button class="chip ${ui.calendarMode === 'month' ? 'active' : ''}" data-action="calendar-mode" data-value="month">Mês</button><button class="chip ${ui.calendarMode === 'week' ? 'active' : ''}" data-action="calendar-mode" data-value="week">Semana</button><button class="chip ${ui.calendarMode === 'agenda' ? 'active' : ''}" data-action="calendar-mode" data-value="agenda">Agenda</button></div><button class="button ghost small">Hoje</button></div>${ui.calendarMode === 'agenda' ? `<div class="event-list">${state.events.map(eventRow).join('')}</div>` : ui.calendarMode === 'week' ? `<div class="card calendar-card"><div class="calendar-toolbar"><button class="icon-button">${icon('back',15)}</button><strong>21 — 27 de setembro de 2026</strong><button class="icon-button">${icon('arrow',15)}</button></div><div class="empty" style="border:0;border-radius:0">${icon('calendar',30)}<strong>Semana de aprendizagem</strong><p>Seus próximos eventos aparecem na agenda.</p></div></div>` : `<div class="card calendar-card"><div class="calendar-toolbar"><button class="icon-button">${icon('back',15)}</button><strong>Setembro de 2026</strong><button class="icon-button">${icon('arrow',15)}</button></div><div class="calendar-grid">${days.map((day) => `<div class="calendar-weekday">${day}</div>`).join('')}${dates.map((number) => { const day = number < 1 ? 31 + number : number > 30 ? number - 30 : number; const muted = number < 1 || number > 30; const events = muted ? [] : dayEvents(day); return `<div class="calendar-day ${muted ? 'muted' : ''}"><span class="calendar-number ${day === 18 && !muted ? 'today' : ''}">${day}</span>${events.map((event) => `<span class="calendar-event" title="${escapeHtml(event.title)}" data-action="show-event" data-id="${event.id}">${escapeHtml(event.title)}</span>`).join('')}</div>`; }).join('')}</div></div>`}<div class="section-heading"><h3>Próximos eventos</h3></div><div class="event-list">${state.events.map(eventRow).join('')}</div>`); }
function eventRow(event) { const day = event.date.slice(-2); return `<article class="event-row" data-action="show-event" data-id="${event.id}" tabindex="0"><span class="event-date">${day}<small>SET</small></span><div><strong>${escapeHtml(event.title)}</strong><span>${escapeHtml(getCourse(event.courseId)?.title || '')} · ${escapeHtml(event.time)} · ${escapeHtml(event.type)}</span></div>${icon('chevron',16)}</article>`; }
function renderMessages() { const current = state.messages.find((item) => item.id === ui.messageId) || state.messages[0]; return appShell('messages', 'Mensagens', `${breadcrumbs([{ label: 'Início', route: 'home' }, { label: 'Mensagens' }])}<div class="page-heading"><div><h2>Mensagens</h2><p>Converse com instrutores e equipe de apoio.</p></div><button class="button primary" data-action="new-message">Nova mensagem ${icon('arrow',15)}</button></div><section class="card messages-layout"><div class="message-list"><div class="message-list-header"><label class="search-field"><span class="icon">${icon('search',15)}</span><input type="search" placeholder="Buscar conversa" /></label></div>${state.messages.map((message) => `<div class="message-item ${current.id === message.id ? 'active' : ''}" data-action="select-message" data-id="${message.id}"><span class="avatar">${message.initials}</span><div style="min-width:0;flex:1"><strong>${escapeHtml(message.name)}</strong><p>${escapeHtml(message.preview)}</p></div><time>${escapeHtml(message.time)}</time></div>`).join('')}</div><div class="conversation"><div class="conversation-header"><h3>${escapeHtml(current.name)}</h3><span class="muted">${escapeHtml(current.subject)}</span></div><div class="conversation-body">${current.messages.map((message) => `<div class="bubble ${message.mine ? 'mine' : ''}">${escapeHtml(message.text)}</div>`).join('')}</div><form class="message-compose" data-form="message"><input type="text" placeholder="Escreva uma mensagem..." aria-label="Nova mensagem" required /><button class="button primary small" type="submit">Enviar</button></form></div></section>`); }
function renderNotes() { return appShell('notes', 'Anotações', `${breadcrumbs([{ label: 'Início', route: 'home' }, { label: 'Anotações' }])}<div class="page-heading"><div><h2>Minhas anotações</h2><p>Guarde lembretes para acompanhar seus cursos.</p></div><button class="button primary" data-action="new-note">Nova anotação ${icon('arrow',15)}</button></div><div class="note-grid">${state.notes.map((note) => `<article class="note"><h3>${escapeHtml(note.title)}</h3><p>${escapeHtml(note.body)}</p><div class="course-footer"><span>${escapeHtml(getCourse(note.courseId)?.title || '')}</span><button class="icon-button" data-action="edit-note" data-id="${note.id}" aria-label="Editar anotação">${icon('edit',15)}</button></div></article>`).join('')}</div>`); }
function renderNotifications() { return appShell('notifications', 'Notificações 👀', `${breadcrumbs([{ label: 'Início', route: 'home' }, { label: 'Notificações' }])}<div class="notifications-page"><div class="drawer-tabs"><button class="active">Todas</button><button>Cursos</button><button>Sistema</button></div><div class="notifications-toolbar"><button class="mark-all" data-action="mark-notifications">${icon('check',15)} Marcar todas como lidas</button></div><div class="notification-group-title">HOJE</div><div class="notifications-page-list">${state.notifications.slice(0, 2).map((item) => `<article class="notification-page-card"><span class="drawer-notification-icon">${icon('bell',18)}</span><div><strong>${escapeHtml(item.title)}</strong><p>${escapeHtml(item.body)}</p></div><time>${escapeHtml(item.time)}</time>${item.unread ? '<span class="notification-dot"></span>' : ''}</article>`).join('')}</div><div class="notification-group-title notification-group-yesterday">ONTEM</div><div class="notifications-page-list">${state.notifications.slice(2).map((item) => `<article class="notification-page-card"><span class="drawer-notification-icon">${icon('clock',18)}</span><div><strong>${escapeHtml(item.title)}</strong><p>${escapeHtml(item.body)}</p></div><time>${escapeHtml(item.time)}</time></article>`).join('')}</div><button class="load-old-notifications" data-action="load-old-notifications">Carregar notificações antigas ${icon('chevron',15)}</button></div>`); }
function renderGrades() { return appShell('grades', 'Notas', `${breadcrumbs([{ label: 'Início', route: 'home' }, { label: 'Notas' }])}<div class="page-heading"><div><h2>Notas</h2><p>Veja seu desempenho nas atividades dos cursos.</p></div></div><div class="stats"><div class="stat"><strong>8,9</strong><span>Média geral</span></div><div class="stat"><strong>12</strong><span>Atividades concluídas</span></div><div class="stat"><strong>3</strong><span>Cursos acompanhados</span></div></div><div class="card table-card"><table><thead><tr><th>Curso</th><th>Atividade</th><th>Nota</th><th>Status</th></tr></thead><tbody>${state.grades.map((grade) => `<tr><td>${escapeHtml(getCourse(grade.courseId)?.title || '')}</td><td>${escapeHtml(grade.activity)}</td><td><strong>${escapeHtml(grade.score)}</strong></td><td><span class="status ${grade.status === 'Pendente' ? 'pending' : 'done'}">${escapeHtml(grade.status)}</span></td></tr>`).join('')}</tbody></table></div>`); }
function renderProfile() { return appShell('profile', 'Perfil', `${breadcrumbs([{ label: 'Início', route: 'home' }, { label: 'Perfil' }])}<div class="profile-banner"><span class="avatar">${state.user.avatar}</span><div><h2>${escapeHtml(state.user.name)}</h2><p>${escapeHtml(state.user.role)} · ${escapeHtml(state.user.company)}</p></div><button class="button secondary" style="margin-left:auto;position:relative;z-index:1" data-action="edit-profile">Editar perfil</button></div><div class="section-heading"><h3>Informações pessoais</h3></div><section class="card form-card"><div class="form-grid"><div class="field"><label>Nome completo</label><input value="${escapeHtml(state.user.name)}" readonly /></div><div class="field"><label>E-mail</label><input value="${escapeHtml(state.user.email)}" readonly /></div><div class="field"><label>CPF</label><input value="${escapeHtml(state.user.cpf)}" readonly /></div><div class="field"><label>Telefone</label><input value="${escapeHtml(state.user.phone)}" readonly /></div></div></section><div class="section-heading"><h3>Cursos recentes</h3></div><div class="card-grid two">${state.courses.filter((course) => course.status === 'done' || course.status === 'progress').slice(0,2).map(courseCard).join('')}</div>`); }
function renderSettings() { return appShell('settings', 'Preferências', `${breadcrumbs([{ label: 'Início', route: 'home' }, { label: 'Preferências' }])}<div class="page-heading"><div><h2>Preferências</h2><p>Personalize a forma como você usa a plataforma.</p></div></div><section class="setting-list"><div class="setting-row"><div><strong>Notificações por e-mail</strong><p>Receba lembretes e novidades dos seus cursos.</p></div><button class="switch ${state.preferences.emailNotifications ? 'on' : ''}" data-action="toggle-email" aria-label="Alternar notificações"></button></div><div class="setting-row"><div><strong>Idioma</strong><p>Idioma usado nos textos da plataforma.</p></div><select data-action="language"><option ${state.preferences.language.startsWith('Português') ? 'selected' : ''}>Português (Brasil)</option><option ${state.preferences.language === 'English' ? 'selected' : ''}>English</option></select></div><div class="setting-row"><div><strong>Resumo de e-mails</strong><p>Escolha como deseja receber mensagens dos fóruns.</p></div><select data-action="digest"><option ${state.preferences.digest === 'Sem resumo' ? 'selected' : ''}>Sem resumo</option><option ${state.preferences.digest === 'Completo' ? 'selected' : ''}>Completo</option><option ${state.preferences.digest === 'Assunto' ? 'selected' : ''}>Assunto</option></select></div></section>`); }
function renderHelp() { const faqs = ['Como emitir meu certificado?', 'Esqueci minha senha, o que fazer?', 'Posso acessar os cursos offline?', 'Como entrar em contato com o instrutor?', 'Como funciona a conclusão de um curso?']; const results = faqs.filter((item) => item.toLowerCase().includes(ui.helpSearch.toLowerCase())); const categories = [{ iconName: 'help', title: 'Dúvidas Frequentes', body: 'Encontre tudo sobre o ambiente virtual de aprendizagem (AVA).' }, { iconName: 'user', title: 'Conta e Perfil', body: 'Dúvidas sobre gerenciar suas informações de conta e perfil.' }, { iconName: 'book', title: 'Navegação e Interface', body: 'Como utilizar a interface e navegar de forma eficiente.' }, { iconName: 'certificate', title: 'Cursos e Conteúdo', body: 'Acessar cursos e conteúdos disponíveis na plataforma.' }, { iconName: 'settings', title: 'Configurações e Preferências', body: 'Personalize sua experiência na plataforma, ajuste notificações e configure preferências de uso.' }]; return appShell('help', 'Central de ajuda 💯', `${breadcrumbs([{ label: 'Início', route: 'home' }, { label: 'Central de ajuda' }])}<div class="help-hero"><span class="help-eyebrow">CENTRAL DE AJUDA</span><h2>Como podemos ajudar você hoje?</h2><div class="help-search"><span>${icon('search',22)}</span><input type="search" value="${escapeHtml(ui.helpSearch)}" placeholder="Pesquisar por artigos, tutoriais ou dúvidas..." aria-label="Pesquisar por artigos, tutoriais ou dúvidas" data-action="help-search" /><button class="button primary" data-action="help-search-submit">Buscar</button></div></div><div class="help-category-grid">${categories.map((category, index) => `<button class="help-category-card ${index === 0 ? 'active' : ''}" data-action="help-category"><span>${icon(category.iconName,28)}</span><strong>${category.title}</strong><p>${category.body}</p></button>`).join('')}</div><section class="help-faq"><h2>Perguntas Frequentes</h2><p>As respostas rápidas para as dúvidas mais comuns dos nossos alunos.</p>${results.length ? results.map((item) => `<button class="help-faq-row" data-action="toggle-faq" data-faq="${escapeHtml(item)}" aria-expanded="${ui.helpFaq === item}"><span>${escapeHtml(item)}</span>${icon("plusCircle",18)}</button>${ui.helpFaq === item ? "<p class=\"help-faq-answer\">A conclusão do curso acontece quando todos os conteúdos obrigatórios são concluídos. O progresso chega a 100% e o certificado é liberado.</p>" : ""}`).join("") : `<div class="empty">${icon('search',30)}<strong>Não encontramos esse conteúdo</strong><p>Tente buscar por outros termos.</p></div>`}</section><div class="help-contact"><div><h3>Não encontrou o que procurava?</h3><p>Nossa equipe de suporte está pronta para ajudar você no que precisar.</p></div><button class="button primary small" data-action="contact">Enviar e-mail ${icon('send',13)}</button></div>`); }

function recommendationModalMarkup() { const step = ui.recommendationStep; const draft = ui.recommendationDraft || { interests: [], goal: '' }; const selectedInterestCount = draft.interests.length; return `<div class="modal-backdrop" data-action="close-modal"><section class="modal recommendation-modal" role="dialog" aria-modal="true" aria-labelledby="recommendation-title"><div class="modal-header"><div><span class="recommendation-kicker">PERSONALIZAÇÃO</span><h2 id="recommendation-title">Personalize suas recomendações</h2></div><button class="close" data-action="close-modal" aria-label="Fechar personalização">${icon('close',16)}</button></div><div class="recommendation-step"><span>Etapa ${step} de 2</span><div class="progress-line"><span style="width:${step === 1 ? 50 : 100}%"></span></div></div>${step === 1 ? `<div class="recommendation-question"><h3>Quais temas você tem interesse em aprender?</h3><p>Selecione os assuntos que mais combinam com seus interesses.</p><div class="recommendation-choice-grid">${RECOMMENDATION_INTERESTS.map((interest) => `<button class="recommendation-choice ${draft.interests.includes(interest) ? 'selected' : ''}" data-action="toggle-recommendation-interest" data-value="${escapeHtml(interest)}">${escapeHtml(interest)}${draft.interests.includes(interest) ? icon('check',15) : ''}</button>`).join('')}</div></div><div class="modal-footer"><span class="recommendation-selection-count">${selectedInterestCount ? `${selectedInterestCount} selecionado${selectedInterestCount === 1 ? '' : 's'}` : 'Selecione pelo menos um tema'}</span><button class="button primary" data-action="next-recommendation" ${selectedInterestCount ? '' : 'disabled'}>Continuar ${icon('arrow',15)}</button></div>` : `<div class="recommendation-question"><h3>Qual é o seu principal objetivo?</h3><p>Escolha uma opção para orientar suas próximas recomendações.</p><div class="recommendation-goal-list">${RECOMMENDATION_GOALS.map((goal) => `<button class="recommendation-goal ${draft.goal === goal ? 'selected' : ''}" data-action="select-recommendation-goal" data-value="${escapeHtml(goal)}"><span class="recommendation-radio">${draft.goal === goal ? icon('check',13) : ''}</span><span>${escapeHtml(goal)}</span></button>`).join('')}</div></div><div class="modal-footer"><button class="button ghost" data-action="back-recommendation">${icon('back',15)} Voltar</button><button class="button primary" data-action="save-recommendations" ${draft.goal ? '' : 'disabled'}>Salvar preferências ${icon('check',15)}</button></div>`}</section></div>`; }
function showModal(type, payload = {}) { ui.modal = { type, ...payload }; if (type === 'recommendations') { ui.recommendationStep = 1; ui.recommendationDraft = { interests: [...(state.preferences.recommendationInterests || [])], goal: state.preferences.recommendationGoal || '' }; } render(); }
function modalMarkup() { if (!ui.modal) return ''; const type = ui.modal.type; if (type === 'recommendations') return recommendationModalMarkup(); if (type === 'forgot') return `<div class="modal-backdrop" data-action="close-modal"><section class="modal" role="dialog" aria-modal="true" aria-labelledby="modal-title"><div class="modal-header"><h2 id="modal-title">Esqueceu a senha?</h2><button class="close" data-action="close-modal" aria-label="Fechar">${icon('close',16)}</button></div><p class="muted">Insira seu e-mail para receber um link de recuperação.</p><div class="field" style="margin-top:18px"><label for="recover-email">E-mail</label><input id="recover-email" type="email" placeholder="nome@empresa.com.br" /></div><div class="modal-footer"><button class="button ghost" data-action="close-modal">Cancelar</button><button class="button primary" data-action="send-recovery">Enviar link</button></div></section></div>`; if (type === 'contact') return `<div class="modal-backdrop" data-action="close-modal"><section class="modal" role="dialog" aria-modal="true" aria-labelledby="modal-title"><div class="modal-header"><h2 id="modal-title">Fale conosco</h2><button class="close" data-action="close-modal" aria-label="Fechar">${icon('close',16)}</button></div><p class="muted">Envie sua dúvida e nossa equipe responderá por e-mail.</p><div class="form-grid" style="margin-top:18px"><div class="field full"><label for="contact-subject">Assunto</label><input id="contact-subject" placeholder="Como podemos ajudar?" /></div><div class="field full"><label for="contact-message">Mensagem</label><textarea id="contact-message" placeholder="Descreva sua dúvida..."></textarea></div></div><div class="modal-footer"><button class="button ghost" data-action="close-modal">Cancelar</button><button class="button primary" data-action="send-contact">Enviar mensagem</button></div></section></div>`; if (type === 'event') { const event = state.events.find((item) => item.id === ui.modal.id); return `<div class="modal-backdrop" data-action="close-modal"><section class="modal" role="dialog" aria-modal="true"><div class="modal-header"><h2>${escapeHtml(event?.title || 'Evento')}</h2><button class="close" data-action="close-modal" aria-label="Fechar">${icon('close',16)}</button></div><p class="muted">${escapeHtml(event?.type || '')} · ${escapeHtml(event?.time || '')}</p><p style="line-height:1.6">Este evento está relacionado ao curso <strong>${escapeHtml(getCourse(event?.courseId)?.title || '')}</strong>. Acesse o conteúdo para continuar sua preparação.</p><div class="modal-footer"><button class="button ghost" data-action="close-modal">Fechar</button><button class="button primary" data-route="course" data-id="${event?.courseId}">Acessar curso</button></div></section></div>`; } if (type === 'new-note') return `<div class="modal-backdrop" data-action="close-modal"><section class="modal" role="dialog" aria-modal="true"><div class="modal-header"><h2>Nova anotação</h2><button class="close" data-action="close-modal" aria-label="Fechar">${icon('close',16)}</button></div><div class="field"><label for="note-title">Título</label><input id="note-title" placeholder="Ex.: Pontos importantes" /></div><div class="field" style="margin-top:15px"><label for="note-body">Anotação</label><textarea id="note-body" placeholder="Escreva uma anotação..."></textarea></div><div class="modal-footer"><button class="button ghost" data-action="close-modal">Cancelar</button><button class="button primary" data-action="save-note">Salvar</button></div></section></div>`; return ''; }

function parseRoute() { const raw = (window.location.hash || '#home').slice(1); const [name, query = ''] = raw.split('?'); return { name: name || 'home', params: Object.fromEntries(new URLSearchParams(query)) }; }
function render() {
  syncAllCourseProgress();
  const route = parseRoute();
  if (!isSessionActive() && route.name !== 'login') {
    window.location.hash = '#login';
    renderLogin();
    return;
  }
  if (route.name === 'login') {
    renderLogin();
    return;
  }

  let view;
  if (route.name === 'home') view = renderHome();
  else if (route.name === 'courses') view = renderCourses();
  else if (route.name === 'course') view = renderCourse(route.params.id);
  else if (route.name === 'lesson') view = renderLesson(route.params.course, route.params.lesson);
  else if (route.name === 'trails') view = renderTrails();
  else if (route.name === 'trail') view = renderTrail(route.params.id);
  else if (route.name === 'catalog') view = renderCatalog();
  else if (route.name === 'showcase') view = renderCatalog(true);
  else if (route.name === 'calendar') view = renderCalendar();
  else if (route.name === 'certificates') view = renderCertificates();
  else if (route.name === 'certificate') view = renderCertificate(route.params.id);
  else if (route.name === 'grades') view = renderGrades();
  else if (route.name === 'messages') view = renderMessages();
  else if (route.name === 'notes') view = renderNotes();
  else if (route.name === 'notifications') view = renderNotifications();
  else if (route.name === 'profile') view = renderProfile();
  else if (route.name === 'settings') view = renderSettings();
  else if (route.name === 'help') view = renderHelp();
  else view = renderHome();

  app.innerHTML = view;
  if (ui.modal) app.insertAdjacentHTML('beforeend', modalMarkup());
  if (ui.drawer) app.insertAdjacentHTML('beforeend', drawerMarkup());
  if (route.name === 'home' || !route.name) syncHomeCoursesPerPage();
}
// O carrossel de "Meus cursos" mostra uma página por linha do grid; o número de colunas varia com a largura da tela.
function syncHomeCoursesPerPage() {
  const grid = document.querySelector('.app-content .card-grid');
  if (!grid) return;
  const columns = getComputedStyle(grid).gridTemplateColumns.split(' ').filter(Boolean).length;
  if (!columns || columns === ui.homeCoursesPerPage) return;
  const firstVisible = ui.homeCoursePage * ui.homeCoursesPerPage;
  ui.homeCoursesPerPage = columns;
  ui.homeCoursePage = Math.floor(firstVisible / columns);
  render();
}
let homeResizeTimer;
window.addEventListener('resize', () => { clearTimeout(homeResizeTimer); homeResizeTimer = setTimeout(() => { if (document.querySelector('.home-course-carousel, .hero')) syncHomeCoursesPerPage(); }, 150); });
function navigate(route, params = {}) { const query = new URLSearchParams(params).toString(); ui.sidebarOpen = false; ui.drawer = null; ui.drawerFocus = null; ui.drawerFocusSelector = ''; ui.modal = null; if (route === 'course') ui.courseTab = 'content'; window.location.hash = `#${route}${query ? `?${query}` : ''}`; }
function showToast(title, message, type = 'success') { ui.toast = { title, message, type }; const region = document.querySelector('#toast-region'); if (!region) return; const toast = document.createElement('div'); toast.className = `toast ${type}`; toast.innerHTML = `${icon(type === 'error' ? 'help' : 'check',18)}<p><strong>${escapeHtml(title)}</strong><span>${escapeHtml(message)}</span></p>`; region.appendChild(toast); setTimeout(() => toast.remove(), 3600); }

window.addEventListener('hashchange', render);
document.addEventListener('click', (event) => {
  const action = event.target.closest('[data-action]:not(.modal-backdrop)');
  if (!action && event.target.classList.contains('modal-backdrop')) { ui.modal = null; render(); return; }
  if (!action && event.target.classList.contains('drawer-overlay')) { closeDrawer(); return; }
  if (!action) {
    const target = event.target.closest('[data-route]');
    if (target) { event.preventDefault(); const route = target.dataset.route; if (route === 'lesson') navigate('lesson', { course: target.dataset.course, lesson: target.dataset.lesson }); else if (route === 'course' || route === 'trail' || route === 'certificate') navigate(route, { id: target.dataset.id }); else navigate(route); return; }
    const passiveButton = event.target.closest('button');
    if (passiveButton && !passiveButton.disabled) showToast('Ação simulada', 'Esta interação está disponível para o teste de usabilidade.');
    return;
  }
  const name = action.dataset.action;
  if (name === 'open-drawer') openDrawer(action.dataset.drawer);
  if (name === 'close-drawer') closeDrawer();
  if (name === 'toggle-notifications') openDrawer('notifications');
  if (name === 'toggle-sidebar') { ui.sidebarOpen = !ui.sidebarOpen; render(); }
  if (name === 'collapse-sidebar') { if (window.matchMedia('(max-width: 820px)').matches) { ui.sidebarOpen = false; render(); return; } ui.sidebarCollapsed = !ui.sidebarCollapsed; writeSidebarCollapsed(ui.sidebarCollapsed); render(); requestAnimationFrame(() => document.querySelector('[data-action="collapse-sidebar"]')?.focus()); }
  if (name === 'home-courses-page') { ui.homeCoursePage = Math.max(0, ui.homeCoursePage + Number(action.dataset.step || 0)); render(); requestAnimationFrame(() => { const target = document.querySelector('[data-action="home-courses-page"][data-step="' + action.dataset.step + '"]:not([disabled])') || document.querySelector('[data-action="home-courses-page"]:not([disabled])'); target?.focus(); }); }
  if (name === 'home-course-filter') { ui.homeCourseStatus = action.dataset.value; ui.homeCoursePage = 0; render(); }
  if (name === 'home-trail-filter') { ui.homeTrailStatus = action.dataset.value; render(); }
  if (name === 'open-notebook') { ui.activeNotebookId = action.dataset.id; ui.notesView = 'editor'; ui.notesMenuOpen = false; render(); requestAnimationFrame(() => document.querySelector('.notebook-editor-content')?.focus()); }
  if (name === 'notes-back') { ui.notesView = 'list'; ui.notesMenuOpen = false; render(); }
  if (name === 'new-notebook') { ui.notesView = 'create'; ui.notesMenuOpen = false; render(); requestAnimationFrame(() => document.querySelector('#notebook-name')?.focus()); }
  if (name === 'toggle-notes-menu') { ui.notesMenuOpen = !ui.notesMenuOpen; render(); }
  if (name === 'rename-notebook') { const notebook = state.notebooks.find((item) => item.id === ui.activeNotebookId); const title = window.prompt('Nome do caderno', notebook?.title || 'Caderno'); if (notebook && title?.trim()) { notebook.title = title.trim(); notebook.updatedAt = new Date().toISOString(); saveState(); } ui.notesMenuOpen = false; render(); }
  if (name === 'delete-notebook') { const notebook = state.notebooks.find((item) => item.id === ui.activeNotebookId); if (notebook && window.confirm(`Excluir ${notebook.title}?`)) { state.notebooks = state.notebooks.filter((item) => item.id !== notebook.id); saveState(); ui.notesView = 'list'; ui.notesMenuOpen = false; render(); showToast('Caderno excluído', 'A anotação foi removida.'); } }
  if (name === 'drawer-settings' || name === 'notes-drawer-settings') showToast('Configurações', 'As configurações deste drawer estão disponíveis para a simulação.');
  if (name === 'messages-back') { ui.messageDrawerView = 'list'; render(); }
  if (name === 'select-drawer-message') { ui.messageId = action.dataset.id; ui.messageDrawerView = 'conversation'; render(); }
  if (name === 'toggle-accessibility') { ui.accessibility[action.dataset.key] = !ui.accessibility[action.dataset.key]; document.documentElement.classList.toggle('accessibility-large-text', ui.accessibility.largeText); document.documentElement.classList.toggle('accessibility-high-contrast', ui.accessibility.highContrast); document.documentElement.classList.toggle('accessibility-reduced-motion', ui.accessibility.reducedMotion); render(); }
  if (name === 'toggle-message-menu' || name === 'compose-format') showToast('Ação simulada', 'Esta opção está disponível para o teste de usabilidade.');
  if (name === 'notes-editor-format') { const editor = document.querySelector('.notebook-editor-content'); editor?.focus(); const format = action.dataset.format; if (format === 'bold') document.execCommand('bold'); else if (format === 'italic') document.execCommand('italic'); else if (format === 'h2') document.execCommand('formatBlock', false, 'h2'); else if (format === 'list') document.execCommand('insertUnorderedList'); else if (format === 'orderedList') document.execCommand('insertOrderedList'); else if (format === 'link') { const url = window.prompt('URL do link'); if (url) document.execCommand('createLink', false, url); } else showToast('Ferramenta simulada', 'Este recurso está disponível para o teste de usabilidade.');
  }
  if (name === 'toggle-password') { const input = document.querySelector('#password'); input.type = input.type === 'password' ? 'text' : 'password'; }
  if (name === 'forgot-password') showModal('forgot');
  if (name === 'contact') showModal('contact');
  if (name === 'close-modal') { ui.modal = null; render(); }
  if (name === 'course-tab') { ui.courseTab = action.dataset.tab === 'about' ? 'about' : 'content'; render(); return; }
  if (name === 'course-filter') { ui.courseStatus = action.dataset.value; render(); }
  if (name === 'calendar-mode') { ui.calendarMode = action.dataset.value; render(); }
  if (name === 'select-message') { ui.messageId = action.dataset.id; render(); }
  if (name === 'toggle-dark') { state.preferences.darkMode = !state.preferences.darkMode; saveState(); document.documentElement.classList.toggle('dark-mode', state.preferences.darkMode); render(); }
  if (name === 'toggle-email') { state.preferences.emailNotifications = !state.preferences.emailNotifications; saveState(); render(); }
  if (name === 'mark-notifications') { state.notifications.forEach((item) => { item.unread = false; }); saveState(); closeDrawer(); showToast('Tudo certo', 'Suas notificações foram marcadas como lidas.'); }
  if (name === 'complete-lesson' || name === 'submit-activity') { const course = getCourse(action.dataset.course); const lesson = getLesson(course, action.dataset.lesson); if (course && lesson && !lesson.done) { lesson.done = true; syncCourseProgress(course); saveState(); showToast('Progresso atualizado', lesson.type === 'task' ? 'Atividade enviada e aula concluída.' : 'Aula marcada como concluída.'); render(); } }
  if (name === 'start-quiz') { ui.quizMode = 'questions'; ui.quizIndex = 0; ui.quizAnswers = {}; ui.quizFeedback = ''; render(); }
  if (name === 'select-quiz-answer') { const question = QUIZ_QUESTIONS[ui.quizIndex]; ui.quizAnswers[question.id] = action.dataset.value; ui.quizFeedback = ''; render(); }
  if (name === 'quiz-previous') { ui.quizIndex = Math.max(0, ui.quizIndex - 1); render(); }
  if (name === 'quiz-next') { const question = QUIZ_QUESTIONS[ui.quizIndex]; if (!ui.quizAnswers[question.id]) { ui.quizFeedback = 'Selecione uma opção para continuar.'; render(); } else if (ui.quizIndex < QUIZ_QUESTIONS.length - 1) { ui.quizFeedback = ''; ui.quizIndex += 1; render(); } else { const course = getCourse(ui.quizCourseId); const lesson = getLesson(course, ui.quizLessonId); lesson.quizAnswers = { ...ui.quizAnswers }; lesson.quizCompleted = true; lesson.done = true; syncCourseProgress(course); saveState(); ui.quizMode = 'completed'; render(); showToast('Questionário concluído', 'Você concluiu esta atividade.'); } }
  if (name === 'enroll-course') { const course = getCourse(action.dataset.id); if (course && !isCourseEnrolled(course)) { course.enrolled = true; course.progress = 0; course.status = 'pending'; saveState(); navigate('course', { id: course.id }); setTimeout(() => showToast('Inscrição realizada', 'O curso foi adicionado aos seus cursos.'), 0); } }
  if (name === 'open-certificate') { const certificate = getCertificateForCourse(action.dataset.course); if (certificate && isCertificateAvailable(certificate)) navigate('certificate', { id: certificate.id }); else showToast('Certificado indisponível', 'Conclua todos os conteúdos obrigatórios para liberar o certificado.', 'error'); }
  if (name === 'play-video') showToast('Conteúdo simulado', 'O player foi iniciado para o teste de usabilidade.');
  if (name === 'download-material') showToast('Material pronto', 'O download do material foi simulado.');
  if (name === 'download-certificate') { const certificate = state.certificates.find((item) => item.id === action.dataset.id); if (!certificate || !isCertificateAvailable(certificate)) { showToast('Certificado indisponível', 'Conclua todos os conteúdos obrigatórios para liberar o certificado.', 'error'); } else { const link = document.createElement('a'); link.href = `data:text/plain;charset=utf-8,Certificado ${encodeURIComponent(certificate.title)} - ${encodeURIComponent(state.user.name)}`; link.download = 'certificado-ava-ned.txt'; link.click(); showToast('Download iniciado', 'O certificado foi preparado para download.'); } }
  if (name === 'share-certificate') { navigator.clipboard?.writeText(window.location.href); showToast('Link copiado', 'O link do certificado foi copiado para a área de transferência.'); }
  if (name === 'recommendation' || name === 'personalize-recommendations') showModal('recommendations');
  if (name === 'toggle-recommendation-interest') { const value = action.dataset.value; const interests = ui.recommendationDraft.interests; ui.recommendationDraft.interests = interests.includes(value) ? interests.filter((item) => item !== value) : [...interests, value]; render(); }
  if (name === 'next-recommendation') { if (ui.recommendationDraft.interests.length) { ui.recommendationStep = 2; render(); } }
  if (name === 'back-recommendation') { ui.recommendationStep = 1; render(); }
  if (name === 'select-recommendation-goal') { ui.recommendationDraft.goal = action.dataset.value; render(); }
  if (name === 'save-recommendations') { if (ui.recommendationDraft.goal) { state.preferences.recommendationInterests = [...ui.recommendationDraft.interests]; state.preferences.recommendationGoal = ui.recommendationDraft.goal; state.preferences.recommendationsConfigured = true; saveState(); ui.modal = null; ui.recommendationsRevealed = true; render(); showToast('Preferências atualizadas', 'Suas recomendações foram personalizadas.'); } }
  if (name === 'show-event') showModal('event', { id: action.dataset.id });
  if (name === 'new-event') showToast('Evento simulado', 'A criação de eventos está disponível para o teste.');
  if (name === 'new-message') showToast('Nova mensagem', 'Escolha um contato para iniciar uma conversa.');
  if (name === 'new-note') showModal('new-note');
  if (name === 'save-note') { const title = document.querySelector('#note-title')?.value.trim(); const body = document.querySelector('#note-body')?.value.trim(); if (title && body) { state.notes.unshift({ id: `note-${Date.now()}`, title, body, courseId: 'ux' }); saveState(); ui.modal = null; showToast('Anotação salva', 'Sua anotação foi adicionada.'); render(); } }
  if (name === 'edit-profile') showToast('Edição de perfil', 'Os campos de perfil estão prontos para edição.');
  if (name === 'help-article') showToast('Artigo aberto', 'Este conteúdo foi preparado para orientar sua jornada.');
  if (name === 'toggle-faq') { ui.helpFaq = ui.helpFaq === action.dataset.faq ? '' : action.dataset.faq; render(); }
  if (name === 'help-category') { document.querySelectorAll('.help-category-card').forEach((card) => card.classList.remove('active')); action.classList.add('active'); }
  if (name === 'help-search-submit') { document.querySelector('[data-action="help-search"]')?.focus(); }
  if (name === 'load-old-notifications') showToast('Notificações', 'Não há notificações antigas adicionais neste cenário.');
  if (name === 'send-recovery') { ui.modal = null; render(); showToast('Link enviado', 'Verifique seu e-mail para redefinir sua senha.'); }
  if (name === 'send-contact') { ui.modal = null; render(); showToast('Mensagem enviada', 'Nossa equipe responderá em breve.'); }
});
document.addEventListener('submit', (event) => {
  if (event.target.id === 'login-form') {
    event.preventDefault();
    const form = new FormData(event.target);
    const cpf = String(form.get('cpf') || '').replace(/\D/g, '');
    const password = String(form.get('password') || '');
    const error = document.querySelector('#login-error');
    const submit = document.querySelector('#login-submit');
    const isValid = cpf === '123' && password === 'teste';

    if (!isValid) {
      submit.disabled = false;
      submit.innerHTML = `Entrar ${icon('arrow',17)}`;
      error.textContent = 'CPF ou senha inválidos. Tente novamente com os dados de teste.';
      error.classList.add('show');
      return;
    }

    error.classList.remove('show');
    submit.disabled = true;
    submit.textContent = 'Entrando...';
    event.target.querySelectorAll('input, button').forEach((field) => { field.disabled = true; });

    window.setTimeout(() => {
      try {
        setSession(true);
        if (!isSessionActive()) throw new Error('Sessão não foi persistida');
        app.innerHTML = renderHome();
        window.history.replaceState({}, '', `${window.location.pathname}#home`);
      } catch (sessionError) {
        submit.disabled = false;
        submit.innerHTML = `Entrar ${icon('arrow',17)}`;
        event.target.querySelectorAll('input, button').forEach((field) => { field.disabled = false; });
        error.textContent = 'Não foi possível iniciar sua sessão. Tente novamente.';
        error.classList.add('show');
        console.error('Falha ao iniciar sessão simulada:', sessionError);
      }
    }, 450);
    return;
  }

  if (event.target.dataset.form === 'create-notebook') {
    event.preventDefault();
    const title = event.target.querySelector('#notebook-name')?.value.trim();
    if (!title) return;
    const now = new Date().toISOString();
    const id = `notebook-${Date.now()}`;
    state.notebooks = state.notebooks || [];
    state.notebooks.unshift({ id, title, contentHTML: '', createdAt: now, updatedAt: now });
    saveState();
    ui.activeNotebookId = id;
    ui.notesView = 'editor';
    render();
    requestAnimationFrame(() => document.querySelector('.notebook-editor-content')?.focus());
    return;
  }

  if (event.target.dataset.form === 'message' || event.target.dataset.form === 'drawer-message') {
    event.preventDefault();
    const input = event.target.querySelector('input');
    if (input.value.trim()) {
      const current = state.messages.find((item) => item.id === ui.messageId);
      current.messages.push({ text: input.value.trim(), mine: true });
      current.preview = input.value.trim();
      input.value = '';
      saveState();
      render();
    }
  }
});
function refreshSearchInput(action, value) {
  render();
  requestAnimationFrame(() => {
    const input = document.querySelector('[data-action="' + action + '"]');
    input?.focus();
    input?.setSelectionRange(value.length, value.length);
  });
}

document.addEventListener('input', (event) => {
  const action = event.target.dataset.action;
  if (action === 'course-search') { ui.courseSearch = event.target.value; refreshSearchInput('course-search', ui.courseSearch); }
  if (action === 'catalog-search') { ui.catalogSearch = event.target.value; refreshSearchInput('catalog-search', ui.catalogSearch); }
  if (action === 'trail-search') { ui.trailSearch = event.target.value; refreshSearchInput('trail-search', ui.trailSearch); }
  if (action === 'help-search') { ui.helpSearch = event.target.value; refreshSearchInput('help-search', ui.helpSearch); }
  if (action === 'notes-search') { ui.notesSearch = event.target.value; refreshSearchInput('notes-search', ui.notesSearch); }
  if (action === 'notebook-input') {
    const notebook = state.notebooks?.find((item) => item.id === ui.activeNotebookId);
    if (notebook) { notebook.contentHTML = event.target.innerHTML; notebook.updatedAt = new Date().toISOString(); saveState(); }
  }
});
document.addEventListener('change', (event) => { const action = event.target.dataset.action; if (action === 'language') { state.preferences.language = event.target.value; saveState(); showToast('Preferência atualizada', 'Idioma salvo.'); } if (action === 'digest') { state.preferences.digest = event.target.value; saveState(); showToast('Preferência atualizada', 'Resumo de e-mails salvo.'); } });

document.documentElement.classList.toggle('dark-mode', state.preferences.darkMode);
render();

document.addEventListener('keydown', (event) => {
  if (ui.modal && event.key === 'Escape') { event.preventDefault(); ui.modal = null; render(); return; }
  if (!ui.drawer) return;
  if (event.key === 'Escape') { event.preventDefault(); closeDrawer(); return; }
  if (event.key !== 'Tab') return;
  const drawer = document.querySelector('[data-drawer]');
  if (!drawer) return;
  const focusable = [...drawer.querySelectorAll('button:not([disabled]), input:not([disabled]), textarea:not([disabled]), select:not([disabled]), [contenteditable="true"], a[href], [tabindex]:not([tabindex="-1"])')];
  if (!focusable.length) { event.preventDefault(); drawer.focus(); return; }
  const first = focusable[0];
  const last = focusable[focusable.length - 1];
  if (event.shiftKey && document.activeElement === first) { event.preventDefault(); last.focus(); }
  else if (!event.shiftKey && document.activeElement === last) { event.preventDefault(); first.focus(); }
});
